ROOT.scriptdef:
CREATE trigger CDN.SISDefinicje_Konta_Init on CDN.SISDefinicje for insert,update as begin
if not UPDATE(SID_Algorytm) return;
delete from cdn.SISDefinicjeKonta where exists(select 1 from inserted i join deleted d on i.SID_GIDNumer=d.SID_GIDNumer and d.SID_GIDNumer=SISK_SISNumer )
;with k as ( select distinct SID_GIDNumer, k1.Konto from inserted i cross apply cdn.KsiKontaWyrazeniaZestawienia(i.SID_Algorytm) k1 )
insert into cdn.SISDefinicjeKonta (SISK_SISNumer, SISK_Lp, SISK_Konto, SISK_KlasaKonta) select SID_GIDNumer , ROW_NUMBER() OVER(PARTITION BY SID_GIDNumer ORDER BY k.Konto ASC) , case when left(k.Konto, 1) <> '@' then k.Konto else '' end , case when left(k.Konto, 1) = '@' then SUBSTRING(k.Konto, 2, len(k.Konto)-1) else '' end from k
end;
